/// Determines if a string is a palindrome, ignoring case and non-letter/digit characters.
///
/// # Examples
///
/// ```
/// assert_eq!(is_palindrome("A man, a plan, a canal, Panama!"), true);
/// assert_eq!(is_palindrome("No lemon, no melon"), true);
/// assert_eq!(is_palindrome("Hello, World!"), false);
/// assert_eq!(is_palindrome("1234567890"), true);
/// assert_eq!(is_palindrome("123456789"), false);
/// ```
fn is_palindrome(s: &str) -> bool {
    // Normalize the string by removing non-letter/digit characters and converting to lowercase
    let filtered_chars: Vec<char> = s.chars()
        .filter(|c| c.is_alphanumeric() && c.is_ascii_lowercase())
        .collect();
    // Check if the filtered string is a palindrome
    filtered_chars == filtered_chars.iter().rev().cloned().collect::<Vec<char>>()
}

