/// Encodes a string into run-length encoding.
///
/// # Examples
///
/// ```
/// assert_eq!(rle("aaabcc"), "3a1b2c");
/// assert_eq!(rle(""), "");
/// ```
fn rle(input: &str) -> String {
    let mut encoded = String::new();
    let mut count = 0;

    for c in input.chars() {
        if c == input[count] {
            count += 1;
        } else {
            encoded.push_str(&format!("{}{}", count, c));
            count = 1;
        }
    }

    if count > 0 {
        encoded.push_str(&format!("{}{}", count, c));
    }

    encoded
}

