use std::collections::HashMap;

/// Counts the occurrences of each word in a given text.
///
/// # Examples
///
/// ```
/// assert_eq!(word_count("Hello world!"), HashMap::from([("hello", 1), ("world", 1)]));
/// assert_eq!(word_count("Rust is fun"), HashMap::from([("rust", 1), ("is", 1), ("fun", 1)]));
/// ```
fn word_count(text: &str) -> HashMap<String, usize> {
    let mut word_map = HashMap::new();
    for word in text.split_whitespace() {
        let lower_word = word.to_lowercase();
        *word_map.entry(lower_word).or_insert(0) += 1;
    }
    word_map
}

