// Import necessary packages
use std::collections::HashSet;

/// Determines if two strings are anagrams of each other, ignoring case and spaces.
///
/// # Examples
///
/// ```
/// assert_eq!(is_anagram("listen", "silent"), true);
/// assert_eq!(is_anagram("hello", "billion"), false);
/// assert_eq!(is_anagram("apple", "papel"), true);
/// assert_eq!(is_anagram("orange", "melon"), false);
/// ```
fn is_anagram(a: &str, b: &str) -> bool {
    // Convert both strings to lowercase and remove spaces
    let cleaned_a: String = a.to_lowercase().replace(" ", "");
    let cleaned_b: String = b.to_lowercase().replace(" ", "");

    // Use a HashSet to count occurrences of each character
    let mut char_counts: HashSet<char> = HashSet::new();

    for c in cleaned_a.chars() {
        char_counts.insert(c);
    }

    for c in cleaned_b.chars() {
        char_counts.insert(c);
    }

    // If the size of the HashSet is the same as the number of characters in the strings, they are anagrams
    char_counts.len() == cleaned_a.len() && char_counts.len() == cleaned_b.len()
}

// Check function to verify the correctness of the solution
fn check() {
    assert_eq!(is_anagram("listen", "silent"), true);
    assert_eq!(is_anagram("hello", "billion"), false);
    assert_eq!(is_anagram("apple", "papel"), true);
    assert_eq!(is_anagram("orange", "melon"), false);
    println!("All tests passed successfully!");
}

