/// Calculates the factorial of a given non-negative integer `n`.
///
/// # Examples
///
/// ```
/// assert_eq!(factorial(5), Some(120));
/// assert_eq!(factorial(0), Some(1));
/// assert_eq!(factorial(10), Some(3628800));
/// ```
fn factorial(n: u32) -> Option<u64> {
    if n == 0 {
        Some(1)
    } else {
        let mut result = 1;
        for i in 1..=n {
            result *= i;
        }
        Some(result)
    }
}

