/// ```
fn find(v: &[i32], target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = v.len() - 1;

    while left <= right {
        let mid = left + (right - left) / 2;

        match v[mid] {
            target => Some(mid),
            _ => {
                if v[mid] > target {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
        }
    }

    None
}

