/// Converts a given integer to its binary representation as a string, without any leading zeros.
/// 
/// # Examples
/// 
/// ```
/// assert_eq!(to_binary(0), "0");
/// assert_eq!(to_binary(5), "101");
/// assert_eq!(to_binary(15), "1111");
/// ```
fn to_binary(n: u32) -> String {
    if n == 0 {
        return "0".to_string();
    }
    let mut binary_str = String::new();
    let mut current_digit = n;

    while current_digit > 0 {
        binary_str = format!("1{binary_str}");
        current_digit /= 2;
    }

    binary_str
}

