/// Shifts each ASCII letter forward by shift positions in the alphabet,
/// wrapping around and keeping its case. Other characters stay as they are.
/// 
/// # Examples
/// 
/// ```
/// assert_eq!(caesar("hello", 3), "lmip");
/// assert_eq!(caesar("world", 2), "asvph");
/// ```
fn caesar(s: &str, shift: u8) -> String {
    s.chars()
        .map(|c| {
            if c.is_ascii_lowercase() {
                ((c as u8 - 'a' + shift) % 26) + 'a'
            } else if c.is_ascii_uppercase() {
                ((c as u8 - 'A' + shift) % 26) + 'A'
            } else {
                c
            }
        })
        .collect()
}

