/// Removes consecutive repeated values from a vector and returns a new vector with unique elements.
///
/// # Examples
///
/// ```
/// assert_eq!(dedup(vec![1, 2, 3, 4, 5, 6, 7, 8, 9]), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);
/// assert_eq!(dedup(vec![1, 2, 2, 3, 4, 5, 6, 7, 8, 9]), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);
/// assert_eq!(dedup(vec![1, 2, 3, 4, 5, 6, 7, 8, 9]), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);
/// ```
fn dedup(v: &[i32]) -> Vec<i32> {
    let mut result = Vec::new();
    let mut current = None;

    for &item in v {
        if current.is_none() || current.unwrap() != item {
            result.push(current.unwrap());
            current = Some(item);
        }
    }

    result
}

// Function to check the correctness of the dedup function
fn check_dedup() {
    assert_eq!(dedup(vec![1, 2, 3, 4, 5, 6, 7, 8, 9]), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);
    assert_eq!(dedup(vec![1, 2, 2, 3, 4, 5, 6, 7, 8, 9]), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);
    assert_eq!(dedup(vec![1, 2, 3, 4, 5, 6, 7, 8, 9]), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);
