use std::collections::VecDeque;

/// Checks if the brackets in a string are balanced.
/// 
/// # Examples
/// 
/// ```
/// assert_eq!(is_balanced(String::from("()")), true);
/// assert_eq!(is_balanced(String::from("[]")), true);
/// assert_eq!(is_balanced(String::from("{}")), true);
/// assert_eq!(is_balanced(String::from(")(")), false);
/// assert_eq!(is_balanced(String::from("[]()")), true);
/// assert_eq!(is_balanced(String::from("[]{}")), true);
/// assert_eq!(is_balanced(String::from("][")), false);
/// ```
fn is_balanced(s: &str) -> bool {
    let mut stack: VecDeque<char> = VecDeque::new();

    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push_back(c),
            ')' | ']' | '}' => {
                if stack.is_empty() {
                    return false;
                }
                stack.pop_back();
            }
            _ => {}
        }
    }

    stack.is_empty()
}

