/// assert_eq!(median(vec![]), None);
/// ```
fn median(v: &[f64]) -> Option<f64> {
    if v.is_empty() {
        return None;
    }

    let mut sorted_v = v.to_vec();
    sorted_v.sort_unstable();

    let mid = sorted_v.len() / 2;
    if sorted_v.len() % 2 == 0 {
        Some((sorted_v[mid - 1] + sorted_v[mid]) / 2.0)
    } else {
        Some(sorted_v[mid])
    }
}

