/// Transpose a rectangular matrix represented as a vector of vectors.
///
/// # Examples
///
/// ```
/// assert_eq!(transpose(vec![vec![1, 2], vec![3, 4]]), vec![vec![1, 3], vec![2, 4]]);
/// assert_eq!(transpose(vec![vec![1, 2], vec![3, 4], vec![5, 6]]), vec![vec![1, 5], vec![2, 6], vec![3, 4]]);
/// ```
fn transpose(m: &[Vec<i32>]) -> Vec<Vec<i32>> {
    if m.is_empty() {
        return Vec::new();
    }

    let mut transposed = Vec::new();
    for (i, row) in m.iter().enumerate() {
        let mut col = Vec::new();
        for (j, &val) in row.iter().enumerate() {
            col.push(val);
        }
        transposed.push(col);
    }

    transposed
}

