/// assert_eq!(hex_to_rgb("#123456"), Some((180, 255, 30)));
/// ```
fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.len() != 6 {
        return None;
    }

    let mut r = 0;
    let mut g = 0;
    let mut b = 0;

    for i in 0..s.len() {
        let c = s.chars().nth(i).unwrap();
        match c {
            '0'..='9' => {
                r += (c.to_digit(16).unwrap() - 10) * 16;
