use std::collections::HashMap;

/// Parses a string containing key-value pairs separated by semicolons into a map.
/// Pairs are separated by ";", and each pair is "key=value".
/// Pairs without "=" are ignored.
///
/// # Examples
///
/// ```
/// assert_eq!(parse_kv("a=1;b=two"), HashMap::from([("a", "1"), ("b", "two")]));
/// assert_eq!(parse_kv("key1=value2;key2=value3"), HashMap::from([("key1", "value2"), ("key2", "value3")]));
/// ```
fn parse_kv(s: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();
    for line in s.split(';') {
        let parts: Vec<&str> = line.trim().splitn(2, |c| c == '=').collect();
        if parts.len() == 2 {
            map.insert(parts[0].to_string(), parts[1].to_string());
        }
    }
    map
}

// Function to check the correctness of the parse_kv function
fn check() {
    assert_eq!(parse_kv("a=1;b=two"), HashMap::from([("a", "1"), ("b", "two")]));
    assert_eq!(parse_kv("key1=value2;key2=value3"), HashMap::from([("key1", "value2"), ("key2", "value3")]));
    assert_eq!(parse_kv("a=1;b=2"), HashMap::from([("a", "1"), ("b", "2")]));
    assert_eq!(parse_kv("a=1;b=2;c=3"), HashMap::from([("a", "1"), ("b", "2"), ("c", "3")]));
    println!("All tests passed successfully!");
}

