// Define the function to calculate the running sum of a vector
pub fn running_sum(v: &[i32]) -> Vec<i32> {
    // Initialize an empty vector to store the running sums
    let mut running_sums: Vec<i32> = Vec::new();

    // If the vector is empty, return an empty vector
    if v.is_empty() {
        return running_sums;
    }

    // Start with the first element of the vector
    let mut current_sum = v[0];

    // Iterate over the vector starting from the second element
    for &num in v.iter().skip(1) {
        // Add the current element to the running sum
        current_sum += num;

        // Append the running sum to the result vector
        running_sums.push(current_sum);
    }

    // Return the vector containing the running sums
    running_sums
}

